import{_ as e,o as a,c as s,ai as o}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"记忆与偏好","description":"Bot 会记住什么、不该依赖它记什么，以及怎样把偏好\\"教\\"给它。","frontmatter":{"related":["/automation/skills","/automation/multi-bot-teamwork","/start/create-first-bot"],"title":"记忆与偏好","description":"Bot 会记住什么、不该依赖它记什么，以及怎样把偏好\\"教\\"给它。","section":"basics","order":2,"tags":["基础","记忆","偏好"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/overview"],"wordCount":531,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"记忆与偏好 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"Bot 会记住什么、不该依赖它记什么，以及怎样把偏好\\"教\\"给它。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/basics/memory-preferences"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/basics-memory-preferences-76d449dd4a.png"}],["meta",{"property":"og:image:alt","content":"记忆与偏好 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"记忆与偏好 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"Bot 会记住什么、不该依赖它记什么，以及怎样把偏好\\"教\\"给它。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/basics-memory-preferences-76d449dd4a.png"}],["meta",{"name":"twitter:image:alt","content":"记忆与偏好 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/basics/memory-preferences"}]]},"headers":[],"relativePath":"basics/memory-preferences.md","filePath":"basics/memory-preferences.md","lastUpdated":1792485206000}'),i={name:"basics/memory-preferences.md"};function n(r,t,l,p,c,d){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="记忆与偏好" tabindex="-1">记忆与偏好 <a class="header-anchor" href="#记忆与偏好" aria-label="Permalink to &quot;记忆与偏好&quot;">​</a></h1><p>用了一周以后，你会发现 Bot 越来越&quot;懂你&quot;：知道你喜欢表格、知道周报要发给谁、知道哪类事一定要先问你。这靠的是它的记忆。</p><h2 id="它会记住什么" tabindex="-1">它会记住什么 <a class="header-anchor" href="#它会记住什么" aria-label="Permalink to &quot;它会记住什么&quot;">​</a></h2><ul><li><strong>稳定的偏好</strong>：输出格式、语气、语言、常用称呼。</li><li><strong>角色和职责</strong>：它是谁、负责什么、边界在哪。</li><li><strong>重要事实</strong>：常用的文件位置、项目名称、固定的协作对象。</li><li><strong>过往工作的摘要</strong>：做过什么、结论是什么，而不是逐字记住每条消息。</li></ul><p>每个 Bot 有自己的对话和记忆，彼此独立。需要在多个 Bot 之间共享的信息，可以通过云电脑上的共享文件、或让 Bot 之间直接发消息交接来传递。产品也在逐步加强跨 Bot 共享的记忆能力，具体范围以官方最新说明为准。</p><h2 id="怎么-教-它" tabindex="-1">怎么&quot;教&quot;它 <a class="header-anchor" href="#怎么-教-它" aria-label="Permalink to &quot;怎么&quot;教&quot;它&quot;">​</a></h2><p>区分两种话：</p><ul><li><strong>长期规则</strong>：加上&quot;以后都……，请记住&quot;。<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从现在开始，任何对外发送的消息都必须先给我审核。请记住。</span></span></code></pre></div></li><li><strong>一次性任务</strong>：正常说就行，不用让它记。<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这 12 个客户的跟进邮件都起草出来。</span></span></code></pre></div></li></ul><p>偏好改了，就直接纠正：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>之前说周报用表格，现在改成分段文字，每段不超过 3 行。请更新你的记忆。</span></span></code></pre></div><p>想检查它记住了什么：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把你目前记住的关于我的偏好和工作规则列出来，我看看有没有过时的。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">一个 Bot 一个角色</p><p>让同一个 Bot 既写代码又管家务，它的记忆会变得混杂。按角色拆成几个 Bot，每个的记忆都会更干净、更准。</p></div><h2 id="不要依赖记忆的地方" tabindex="-1">不要依赖记忆的地方 <a class="header-anchor" href="#不要依赖记忆的地方" aria-label="Permalink to &quot;不要依赖记忆的地方&quot;">​</a></h2><p>记忆是&quot;印象&quot;，不是&quot;数据库&quot;。下面这些情况，要让它回到源头查：</p><ul><li>会变化的数据：库存、价格、日程、账户余额。</li><li>重要决策：涉及钱、合同、对外承诺。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>做决定之前，请重新打开最新的数据源核对，不要凭印象。结论里附上数据来源和查询时间。</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">安全边界不能只靠记忆</p><p>&quot;不要发邮件&quot;这样的规则，除了让它记住，还应该配合审批设置（见<a href="/basics/safety-approvals">安全审核与授权</a>）。记忆可能被新的指令覆盖，审批规则才是硬性的那道关。</p></div><h2 id="复制一个-bot-时" tabindex="-1">复制一个 Bot 时 <a class="header-anchor" href="#复制一个-bot-时" aria-label="Permalink to &quot;复制一个 Bot 时&quot;">​</a></h2><p>在部分客户端可以复制一个 Bot 来复用角色。复制品会带上设定、技能和例程，但不会带上对话历史和学到的记忆，复制后记得改名并交代新的范围。</p>',20)])])}const u=e(i,[["render",n]]);export{h as __pageData,u as default};
